function pix=dva2pix(dva, scr)% conversion of degree of visual angle into pixels % inputs :%	va		: x degrees of visual angle%	scr	    : structure describing monitor characteristics. Minimal fields required are listed below%		scr.subDist	: viewing distance [mm]%		scr.width	: physical width of monitor [mm]%		scr.xres    : x resolution of monitorpix = scr.subDist*tan(dva*pi/180)/(scr.width/scr.resX);	% distance between fixation point and target in pixels 